@icontract.ensure(lambda self, candidate, result: (result is None) or isinstance(result, str), "Must return a string path or None.")
@icontract.ensure(lambda self, candidate, result: (result is None) or (result.strip() == result and result != ""), "Returned path, if any, must be a non-empty, trimmed string.")
