@icontract.ensure(lambda self, candidate, result: (("->" not in candidate) and (not candidate.startswith("D")) and (result is not None)) <= (result == candidate[3:].strip()), "On non-rename, non-deletion lines, result must be the path after the first three characters.")
@icontract.ensure(lambda self, candidate, result: (result is None) or ("->" not in result), "Returned path must not contain a rename arrow.")

